# 方法一：兩次掃描（最優解）
class Solution:
    def candy(self, ratings: List[int]) -> int:
        n = len(ratings)
        if n <= 1:
            return n

        # 初始化，每個孩子先給 1 顆糖
        candies = [1] * n

        # 第一次掃描：從左到右
        # 如果比左邊評分高，糖果 = 左邊 + 1
        for i in range(1, n):
            if ratings[i] > ratings[i - 1]:
                candies[i] = candies[i - 1] + 1

        # 第二次掃描：從右到左
        # 如果比右邊評分高，糖果 = max(當前, 右邊 + 1)
        for i in range(n - 2, -1, -1):
            if ratings[i] > ratings[i + 1]:
                candies[i] = max(candies[i], candies[i + 1] + 1)

        return sum(candies)


# 方法二：兩個陣列版本（更清晰）
class Solution:
    def candy(self, ratings: List[int]) -> int:
        n = len(ratings)
        if n <= 1:
            return n

        left = [1] * n
        right = [1] * n

        # 從左到右
        for i in range(1, n):
            if ratings[i] > ratings[i - 1]:
                left[i] = left[i - 1] + 1

        # 從右到左
        for i in range(n - 2, -1, -1):
            if ratings[i] > ratings[i + 1]:
                right[i] = right[i + 1] + 1

        # 取最大值
        return sum(max(l, r) for l, r in zip(left, right))


# 方法三：詳細註解版本
class Solution:
    def candy(self, ratings: List[int]) -> int:
        """
        貪心策略：兩次掃描

        核心思想：
        左右規則可以分開處理，最後取最大值
        """
        n = len(ratings)

        # 邊界情況
        if n <= 1:
            return n

        # 每個孩子至少 1 顆糖
        candies = [1] * n

        # 第一次掃描：處理「比左邊高」的情況
        # 從左到右遍歷
        for i in range(1, n):
            # 如果當前孩子評分比左邊高
            if ratings[i] > ratings[i - 1]:
                # 糖果數 = 左邊孩子 + 1
                candies[i] = candies[i - 1] + 1
            # 如果評分不比左邊高，保持 1 顆（已初始化）

        # 第二次掃描：處理「比右邊高」的情況
        # 從右到左遍歷
        for i in range(n - 2, -1, -1):
            # 如果當前孩子評分比右邊高
            if ratings[i] > ratings[i + 1]:
                # 需要滿足：
                # 1. 比右邊孩子多（右邊 + 1）
                # 2. 同時保持之前從左掃描得到的值
                # 所以取兩者最大值
                candies[i] = max(candies[i], candies[i + 1] + 1)

        # 返回總糖果數
        return sum(candies)


# 方法四：一次掃描（進階，較複雜）
class Solution:
    def candy(self, ratings: List[int]) -> int:
        """
        優化版本：只掃描一次
        時間 O(n)，空間 O(1)
        """
        n = len(ratings)
        if n <= 1:
            return n

        total = 1
        up = 0      # 上升序列長度
        down = 0    # 下降序列長度
        peak = 0    # 峰值糖果數

        for i in range(1, n):
            if ratings[i] > ratings[i - 1]:
                # 上升
                up += 1
                down = 0
                peak = up + 1
                total += peak
            elif ratings[i] == ratings[i - 1]:
                # 相等，重置
                up = down = peak = 0
                total += 1
            else:
                # 下降
                up = 0
                down += 1
                # 如果下降序列長度超過峰值，需要調整峰值
                total += down + (1 if down >= peak else 0)

        return total

